    (() => {
      const root = document.currentScript?.closest('.wa-panel') ?? document.querySelector('.wa-panel');
      if (!root) return;
      const byId = id => root.querySelector(`#${id}`);
      const text = (id, value) => { byId(id).textContent = value ?? '—'; };
      const asArray = value => Array.isArray(value) ? value : [];

      function renderList(node, items, emptyText = '暂无') {
        node.replaceChildren();
        const values = asArray(items);
        if (!values.length) {
          const li = document.createElement('li');
          li.textContent = emptyText;
          li.className = 'wa-muted';
          node.append(li);
          return;
        }
        for (const item of values) {
          const li = document.createElement('li');
          li.textContent = String(item);
          node.append(li);
        }
      }

      function renderRelations(relations) {
        const container = byId('wa-relations');
        container.replaceChildren();
        const unlocked = Object.entries(relations ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlocked.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无核心角色登场。';
          container.append(empty);
          return;
        }
        for (const [name, relation] of unlocked) {
          const row = document.createElement('div');
          row.className = 'wa-person';
          const heading = document.createElement('div');
          heading.className = 'wa-name';
          heading.textContent = `${name}${relation.在场 ? ' · 在场' : ''}`;
          const detail = document.createElement('div');
          const stage = document.createElement('div');
          stage.className = 'wa-stage';
          stage.textContent = `${relation.关系类型 ?? '关系未明'}｜${relation.可见阶段 ?? '阶段未明'}`;
          const cue = document.createElement('div');
          cue.className = 'wa-muted';
          cue.textContent = asArray(relation.可见迹象).slice(-2).join('；') || relation.最近互动 || '暂无可见迹象';
          detail.append(stage, cue);
          row.append(heading, detail);
          container.append(row);
        }
      }

      function render(data) {
        const state = data?.stat_data;
        if (!state) throw new Error('当前楼层还没有初始化变量');

        text('wa-location', state.世界?.地点);
        text('wa-time', `${state.世界?.日期 ?? '—'} · ${state.世界?.时间 ?? '—'} · ${state.世界?.氛围 ?? '—'}`);
        text('wa-task', `${state.系统?.当前任务 ?? '—'}｜${state.系统?.任务状态 ?? '—'}`);
        text('wa-task-note', state.系统?.任务说明);
        text('wa-case', `${state.病例?.阶段 ?? '—'}｜${state.病例?.病患 ?? '—'}：${state.病例?.主诉 ?? '—'}`);
        renderList(byId('wa-clues'), state.病例?.已知线索, '尚无线索');
        text('wa-progress', state.病例?.最近进展);
        renderRelations(state.关系);
        text('wa-main-event', `${state.事件?.主事件?.标题 ?? '—'}｜${state.事件?.主事件?.状态 ?? '—'}`);
        text('wa-main-summary', state.事件?.主事件?.摘要);
        renderList(byId('wa-side-events'), asArray(state.事件?.支线).map(event => `${event.标题}｜${event.状态}`), '暂无活动支线');
        byId('wa-error').hidden = true;
      }

      function showError(error) {
        const node = byId('wa-error');
        node.textContent = `MVU 未就绪，正文仍可使用。${error?.message ? `（${error.message}）` : ''}`;
        node.hidden = false;
      }

      function getHostWindows() {
        const hosts = [globalThis];
        for (const candidate of [globalThis.parent, globalThis.top]) {
          try {
            if (candidate && !hosts.includes(candidate)) hosts.push(candidate);
          } catch {
            // 跨域父页面不可访问时继续使用当前窗口。
          }
        }
        return hosts;
      }

      function findMvu() {
        for (const host of getHostWindows()) {
          try {
            if (host.Mvu?.getMvuData) return host.Mvu;
          } catch {
            // 某一层窗口不可访问时继续向上查找。
          }
        }
        return undefined;
      }

      function getMessageId() {
        if (typeof getCurrentMessageId === 'function') return getCurrentMessageId();
        const match = String(globalThis.name || '').match(/^TH-message--(\d+)--/);
        return match ? Number(match[1]) : 'latest';
      }

      function unwrapMessageVariables(message) {
        const variables = message?.variables;
        if (!variables) return undefined;
        if (Array.isArray(variables)) {
          return variables[message?.swipe_id ?? 0] ?? variables.at(-1);
        }
        if (variables.stat_data) return variables;
        return variables[message?.swipe_id ?? 0];
      }

      function readStoredVariables(messageId) {
        for (const host of getHostWindows()) {
          try {
            const tavern = host.SillyTavern;
            const context = typeof tavern?.getContext === 'function' ? tavern.getContext() : tavern;
            const chat = context?.chat;
            if (!Array.isArray(chat) || !chat.length) continue;
            const message = Number.isInteger(messageId)
              ? chat[messageId]
              : [...chat].reverse().find(item => !item?.is_system);
            let data = unwrapMessageVariables(message);
            if (!data?.stat_data) {
              for (let index = chat.length - 1; index >= 0; index -= 1) {
                data = unwrapMessageVariables(chat[index]);
                if (data?.stat_data) break;
              }
            }
            if (data?.stat_data) return data;
          } catch {
            // 当前宿主入口不可用时尝试下一层窗口。
          }
        }
        return undefined;
      }

      function readCurrent(mvu = findMvu()) {
        try {
          const messageId = getMessageId();
          let data = mvu?.getMvuData({ type: 'message', message_id: messageId });
          if (!data?.stat_data && mvu) {
            data = mvu.getMvuData({ type: 'message', message_id: 'latest' });
          }
          if (!data?.stat_data) data = readStoredVariables(messageId);
          if (!data?.stat_data) throw new Error('当前消息中未找到已保存的 MVU 变量');
          render(data);
        } catch (error) {
          showError(error);
        }
      }

      const tabs = [...root.querySelectorAll('[role="tab"]')];
      function activateTab(next) {
        for (const tab of tabs) {
          const selected = tab === next;
          tab.setAttribute('aria-selected', String(selected));
          tab.tabIndex = selected ? 0 : -1;
          byId(tab.getAttribute('aria-controls')).hidden = !selected;
        }
      }
      tabs.forEach((tab, index) => {
        tab.addEventListener('click', () => activateTab(tab));
        tab.addEventListener('keydown', event => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
          event.preventDefault();
          const offset = event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0;
          const nextIndex = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + offset + tabs.length) % tabs.length;
          tabs[nextIndex].focus();
          activateTab(tabs[nextIndex]);
        });
      });

      const subscriptions = [];
      async function bootstrap() {
        readCurrent();
        let mvu = findMvu();
        for (let attempt = 0; !mvu && attempt < 60; attempt += 1) {
          await new Promise(resolve => setTimeout(resolve, 250));
          mvu = findMvu();
        }
        if (!mvu) return;
        readCurrent(mvu);
        if (mvu.events && typeof eventOn === 'function') {
          const refresh = () => { readCurrent(mvu); };
          subscriptions.push(eventOn(mvu.events.VARIABLE_INITIALIZED, refresh));
          subscriptions.push(eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh));
        }
      }
      window.addEventListener('pagehide', () => subscriptions.forEach(subscription => subscription?.stop?.()), { once: true });
      void bootstrap();
    })();
  </script>
